25→// Skeleton shown during page-to-page navigation transitions inside the app shell.
26→// useNavigation must be called inside PolarisAppProvider so Polaris context is available.
27→function AppContent() {
28→  const navigation = useNavigation();
29→  const isNavigating = navigation.state === "loading";
30→
31→  if (isNavigating) {
32→    return (
33→      <SkeletonPage primaryAction>
34→        <Layout>
35→          <Layout.Section>
36→            <Card>
37→              <SkeletonDisplayText size="small" />
38→              <SkeletonBodyText lines={3} />
39→            </Card>
40→          </Layout.Section>
41→          <Layout.Section>
42→            <Card>
43→              <SkeletonBodyText lines={6} />
44→            </Card>
45→          </Layout.Section>
46→          <Layout.Section>
47→            <Card>
48→              <SkeletonBodyText lines={4} />
49→            </Card>
50→          </Layout.Section>
51→        </Layout>
52→      </SkeletonPage>
53→    );
54→  }
55→
56→  return <Outlet />;
57→}
58→
59→export default function App() {
60→  const { apiKey } = useLoaderData<typeof loader>();
61→
62→  return (
63→    <AppProvider embedded apiKey={apiKey}>
64→      <PolarisAppProvider i18n={enTranslations}>
65→        <s-app-nav>
66→          <s-link href="/app">Dashboard</s-link>
67→          <s-link href="/app/zip-codes">Zip Codes</s-link>
68→          <s-link href="/app/delivery-rules">Delivery Rules</s-link>
69→          <s-link href="/app/waitlist">Waitlist</s-link>
70→          <s-link href="/app/widget">Widget Customization</s-link>
71→          <s-link href="/app/settings">Settings</s-link>
72→          <s-link href="/app/help">Help &amp; Support</s-link>
73→        </s-app-nav>
74→        <AppContent />
75→      </PolarisAppProvider>
76→    </AppProvider>
77→  );
78→}
