   1→import { useState, useCallback, useMemo, useEffect } from "react";
   2→import type {
   3→  ActionFunctionArgs,
   4→  HeadersFunction,
   5→  LoaderFunctionArgs,
   6→} from "react-router";
   7→import { useFetcher, useLoaderData, useNavigate, useRouteError } from "react-router";
   8→import { useAppBridge } from "@shopify/app-bridge-react";
   9→import { authenticate } from "../shopify.server";
  10→import { boundary } from "@shopify/shopify-app-react-router/server";
  11→import db from "../db.server";
  12→import { getShopSubscription } from "../billing.server";
  13→import { PLAN_LIMITS, UNLIMITED } from "../plans";
  14→import {
  15→  Page,
  16→  Layout,
  17→  Card,
  18→  BlockStack,
  19→  InlineStack,
  20→  Text,
  21→  Button,
  22→  TextField,
  23→  Select,
  24→  Modal,
  25→  IndexTable,
  26→  EmptyState,
  27→  Divider,
  28→  Box,
  29→  Tooltip,
  30→  Icon,
  31→  Banner,
  32→  InlineGrid,
  33→  Checkbox,
  34→  type IndexTableProps,
  35→} from "@shopify/polaris";
  36→import {
  37→  SearchIcon,
  38→  DeleteIcon,
  39→  PlusIcon,
  40→  EmailIcon,
  41→} from "@shopify/polaris-icons";
  42→
  43→const PAGE_SIZE = 10;
  44→
  45→export const loader = async ({ request }: LoaderFunctionArgs) => {
  46→  const { session } = await authenticate.admin(request);
  47→  const shop = session.shop;
  48→
  49→  const [entries, subscription] = await Promise.all([
  50→    db.waitlistEntry.findMany({
  51→      where: { shop },
  52→      orderBy: { createdAt: "desc" },
  53→    }),
  54→    getShopSubscription(shop),
  55→  ]);
  56→
  57→  const stats = {
  58→    total: entries.length,
  59→    waiting: entries.filter((e) => e.status === "waiting").length,
  60→    accepted: entries.filter((e) => e.status === "accepted").length,
  61→    rejected: entries.filter((e) => e.status === "rejected").length,
  62→    notified: entries.filter((e) => e.status === "notified").length,
  63→    converted: entries.filter((e) => e.status === "converted").length,
  64→    uniqueZips: [...new Set(entries.map((e) => e.zipCode))].length,
  65→  };
  66→
  67→  return { entries, stats, subscription };
  68→};
  69→
  70→export const action = async ({ request }: ActionFunctionArgs) => {
  71→  const { session } = await authenticate.admin(request);
  72→  const shop = session.shop;
  73→  const formData = await request.formData();
  74→  const intent = formData.get("intent");
  75→
  76→  if (intent === "add") {
  77→    const email = String(formData.get("email") || "").trim().toLowerCase();
  78→    const zipCode = String(formData.get("zipCode") || "")
  79→      .trim()
  80→      .toUpperCase();
  81→    const note = String(formData.get("note") || "").trim() || null;
  82→
  83→    if (!email || !zipCode) return { error: "Email and zip code are required." };
  84→
  85→    const subscription = await getShopSubscription(shop);
  86→    const limits = PLAN_LIMITS[subscription.planTier];
  87→
  88→    if (limits.maxWaitlist === 0) {
  89→      return { error: "Your current plan does not include waitlist access. Upgrade to Starter or higher." };
  90→    }
  91→
  92→    if (limits.maxWaitlist < UNLIMITED) {
  93→      const currentCount = await db.waitlistEntry.count({ where: { shop } });
  94→      if (currentCount >= limits.maxWaitlist) {
  95→        return { error: `You have reached the ${limits.maxWaitlist}-entry waitlist limit on your ${limits.label} plan. Upgrade to Pro for unlimited entries.` };
  96→      }
  97→    }
  98→
  99→    try {
 100→      await db.waitlistEntry.create({
 101→        data: { shop, email, zipCode, note },
 102→      });
 103→      return { success: true, action: "added" };
 104→    } catch {
 105→      return { error: "This email is already on the waitlist for this zip code." };
 106→    }
 107→  }
 108→
 109→  if (intent === "delete") {
 110→    const id = String(formData.get("id"));
 111→    try {
 112→      const existing = await db.waitlistEntry.findFirst({ where: { id, shop } });
 113→      if (!existing) return { error: "Entry not found." };
 114→      await db.waitlistEntry.delete({ where: { id } });
 115→      return { success: true, action: "deleted" };
 116→    } catch {
 117→      return { error: "Failed to delete entry." };
 118→    }
 119→  }
 120→
 121→  if (intent === "update-status") {
 122→    const id = String(formData.get("id"));
 123→    const status = String(formData.get("status"));
 124→    try {
 125→      const existing = await db.waitlistEntry.findFirst({ where: { id, shop } });
 126→      if (!existing) return { error: "Entry not found." };
 127→      await db.waitlistEntry.update({ where: { id }, data: { status } });
 128→      return { success: true, action: "updated" };
 129→    } catch {
 130→      return { error: "Failed to update entry status." };
 131→    }
 132→  }
 133→
 134→  if (intent === "notify-zip") {
 135→    const zipCode = String(formData.get("zipCode") || "").trim().toUpperCase();
 136→    if (!zipCode) return { error: "No ZIP code specified." };
 137→
 138→    const notifyZipSub = await getShopSubscription(shop);
 139→    if (PLAN_LIMITS[notifyZipSub.planTier].maxWaitlist < UNLIMITED) {
 140→      return { error: "Bulk notify is only available on Pro or Ultimate plans. Please upgrade." };
 141→    }
 142→
 143→    const notifyZipEntries = await db.waitlistEntry.findMany({
 144→      where: { shop, zipCode, status: "waiting" },
 145→      select: { id: true, email: true },
 146→    });
 147→
 148→    if (notifyZipEntries.length === 0) {
 149→      return { action: "notify-zip", zipCode, emails: [] as string[], count: 0 };
 150→    }
 151→
 152→    await db.waitlistEntry.updateMany({
 153→      where: { shop, zipCode, status: "waiting" },
 154→      data: { status: "notified" },
 155→    });
 156→
 157→    const emails = notifyZipEntries.map((e) => e.email);
 158→    return { action: "notify-zip", zipCode, emails, count: emails.length };
 159→  }
 160→
 161→  if (intent === "notify-selected-zips") {
 162→    const zipCodesRaw = String(formData.get("zipCodes") || "");
 163→    const zipCodes = zipCodesRaw.split(",").map(z => z.trim().toUpperCase()).filter(Boolean);
 164→    if (zipCodes.length === 0) return { error: "No ZIP codes selected." };
 165→
 166→    const notifyZipsSub = await getShopSubscription(shop);
 167→    if (PLAN_LIMITS[notifyZipsSub.planTier].maxWaitlist < UNLIMITED) {
 168→      return { error: "Bulk notify is only available on Pro or Ultimate plans. Please upgrade." };
 169→    }
 170→
 171→    const waitingEntries = await db.waitlistEntry.findMany({
 172→      where: { shop, status: "waiting", zipCode: { in: zipCodes } },
 173→      select: { id: true, email: true, zipCode: true },
 174→    });
 175→
 176→    if (waitingEntries.length === 0) {
 177→      return { action: "notify-selected-zips", emails: [] as string[], count: 0, zipBreakdown: [] as { zipCode: string; count: number }[] };
 178→    }
 179→
 180→    await db.waitlistEntry.updateMany({
 181→      where: { shop, status: "waiting", zipCode: { in: zipCodes } },
 182→      data: { status: "notified" },
 183→    });
 184→
 185→    const zipMap = new Map<string, number>();
 186→    for (const entry of waitingEntries) {
 187→      zipMap.set(entry.zipCode, (zipMap.get(entry.zipCode) ?? 0) + 1);
 188→    }
 189→    const zipBreakdown = Array.from(zipMap.entries()).map(([zipCode, count]) => ({ zipCode, count }));
 190→    const emails = waitingEntries.map(e => e.email);
 191→
 192→    return { action: "notify-selected-zips", emails, count: emails.length, zipBreakdown };
 193→  }
 194→
 195→  if (intent === "bulk-action") {
 196→    const idsRaw = String(formData.get("ids") || "");
 197→    const ids = idsRaw.split(",").filter(Boolean);
 198→    const bulkType = String(formData.get("bulkType") || "");
 199→
 200→    if (ids.length === 0) return { error: "No entries selected." };
 201→
 202→    const bulkSub = await getShopSubscription(shop);
 203→
 204→    if (bulkType === "notify") {
 205→      if (PLAN_LIMITS[bulkSub.planTier].maxWaitlist < UNLIMITED) {
 206→        return { error: "Bulk notify is only available on Pro or Ultimate plans. Please upgrade." };
 207→      }
 208→      const entriesToNotify = await db.waitlistEntry.findMany({
 209→        where: { id: { in: ids }, shop, status: "waiting" },
 210→        select: { id: true, email: true, zipCode: true },
 211→      });
 212→      if (entriesToNotify.length === 0) {
 213→        return { action: "bulk-action-notify", emails: [] as string[], count: 0, zipBreakdown: [] as { zipCode: string; count: number }[] };
 214→      }
 215→      await db.waitlistEntry.updateMany({
 216→        where: { id: { in: ids }, shop, status: "waiting" },
 217→        data: { status: "notified" },
 218→      });
 219→      const zipMap = new Map<string, number>();
 220→      for (const e of entriesToNotify) {
 221→        zipMap.set(e.zipCode, (zipMap.get(e.zipCode) ?? 0) + 1);
 222→      }
 223→      const zipBreakdown = Array.from(zipMap.entries()).map(([z, c]) => ({ zipCode: z, count: c }));
 224→      return { action: "bulk-action-notify", emails: entriesToNotify.map(e => e.email), count: entriesToNotify.length, zipBreakdown };
 225→    }
 226→
 227→    if (bulkType === "accept") {
 228→      const entriesToAccept = await db.waitlistEntry.findMany({
 229→        where: { id: { in: ids }, shop },
 230→        select: { id: true, email: true, name: true, zipCode: true },
 231→      });
 232→      for (const entry of entriesToAccept) {
 233→        await db.zipCode.upsert({
 234→          where: { shop_zipCode: { shop, zipCode: entry.zipCode } },
 235→          create: { shop, zipCode: entry.zipCode, type: "allowed", isActive: true, label: `Requested by ${entry.name || entry.email}` },
 236→          update: { type: "allowed", isActive: true },
 237→        });
 238→      }
 239→      await db.waitlistEntry.updateMany({
 240→        where: { id: { in: ids }, shop },
 241→        data: { status: "accepted" },
 242→      });
 243→      return { success: true, action: "bulk-accepted", count: entriesToAccept.length };
 244→    }
 245→
 246→    if (bulkType === "reject") {
 247→      const result = await db.waitlistEntry.updateMany({
 248→        where: { id: { in: ids }, shop },
 249→        data: { status: "rejected" },
 250→      });
 251→      return { success: true, action: "bulk-rejected", count: result.count };
 252→    }
 253→
 254→    if (bulkType === "delete") {
 255→      const result = await db.waitlistEntry.deleteMany({
 256→        where: { id: { in: ids }, shop },
 257→      });
 258→      return { success: true, action: "bulk-deleted", count: result.count };
 259→    }
 260→
 261→    return { error: "Unknown bulk action type." };
 262→  }
 263→
 264→  if (intent === "delete-all-notified") {
 265→    const deleted = await db.waitlistEntry.deleteMany({
 266→      where: { shop, status: "notified" },
 267→    });
 268→    return { success: true, action: "deleted-notified", count: deleted.count };
 269→  }
 270→
 271→  if (intent === "accept") {
 272→    const id = String(formData.get("id"));
 273→    const entry = await db.waitlistEntry.findUnique({ where: { id } });
 274→    if (!entry || entry.shop !== shop) {
 275→      return { error: "Entry not found." };
 276→    }
 277→
 278→    await db.zipCode.upsert({
 279→      where: { shop_zipCode: { shop, zipCode: entry.zipCode } },
 280→      create: {
 281→        shop,
 282→        zipCode: entry.zipCode,
 283→        type: "allowed",
 284→        isActive: true,
 285→        label: `Requested by ${entry.name || entry.email}`,
 286→      },
 287→      update: {
 288→        type: "allowed",
 289→        isActive: true,
 290→      },
 291→    });
 292→
 293→    await db.waitlistEntry.update({
 294→      where: { id },
 295→      data: { status: "accepted" },
 296→    });
 297→
 298→    return { success: true, action: "accepted", zipCode: entry.zipCode };
 299→  }
 300→
 301→  if (intent === "reject") {
 302→    const id = String(formData.get("id"));
 303→    try {
 304→      const existing = await db.waitlistEntry.findFirst({ where: { id, shop } });
 305→      if (!existing) return { error: "Entry not found." };
 306→      await db.waitlistEntry.update({
 307→        where: { id },
 308→        data: { status: "rejected" },
 309→      });
 310→      return { success: true, action: "rejected" };
 311→    } catch {
 312→      return { error: "Failed to reject entry." };
 313→    }
 314→  }
 315→
 316→  return null;
 317→};
 318→
 319→type WaitlistEntry = {
 320→  id: string;
 321→  name: string | null;
 322→  email: string;
 323→  zipCode: string;
 324→  note: string | null;
 325→  status: string;
 326→  createdAt: string | Date;
 327→};
 328→
 329→export default function WaitlistPage() {
 330→  const { entries, stats, subscription } = useLoaderData<typeof loader>();
 331→  const fetcher = useFetcher<typeof action>();
 332→  const shopify = useAppBridge();
 333→  const navigate = useNavigate();
 334→
 335→  const limits = PLAN_LIMITS[subscription.planTier];
 336→  const isFreePlan = limits.maxWaitlist === 0;
 337→  const isStarterPlan = limits.maxWaitlist < UNLIMITED && limits.maxWaitlist > 0;
 338→
 339→  const [searchQuery, setSearchQuery] = useState("");
 340→  const [statusFilter, setStatusFilter] = useState("all");
 341→  const [currentPage, setCurrentPage] = useState(1);
 342→  const [addModalOpen, setAddModalOpen] = useState(false);
 343→  const [notifyModalOpen, setNotifyModalOpen] = useState(false);
 344→  const [notifyResultModalOpen, setNotifyResultModalOpen] = useState(false);
 345→  const [notifyResult, setNotifyResult] = useState<{
 346→    zipCode: string;
 347→    emails: string[];
 348→    count: number;
 349→  } | null>(null);
 350→  const [copySuccess, setCopySuccess] = useState(false);
 351→
 352→  // ZIP checkbox selection
 353→  const [selectedZips, setSelectedZips] = useState<Set<string>>(new Set());
 354→
 355→  // IndexTable row selection
 356→  const [selectedEntryIds, setSelectedEntryIds] = useState<string[]>([]);
 357→
 358→  // Form state
 359→  const [newEmail, setNewEmail] = useState("");
 360→  const [newZipCode, setNewZipCode] = useState("");
 361→  const [newNote, setNewNote] = useState("");
 362→
 363→  const actionError =
 364→    fetcher.data && "error" in fetcher.data ? fetcher.data.error : null;
 365→
 366→  // Compute per-ZIP waiting counts for the "Notify Waitlist" section
 367→  const zipWaitingCounts = useMemo(() => {
 368→    const map = new Map<string, number>();
 369→    for (const e of entries as WaitlistEntry[]) {
 370→      if (e.status === "waiting") {
 371→        map.set(e.zipCode, (map.get(e.zipCode) ?? 0) + 1);
 372→      }
 373→    }
 374→    return Array.from(map.entries())
 375→      .map(([zipCode, count]) => ({ zipCode, count }))
 376→      .sort((a, b) => b.count - a.count);
 377→  }, [entries]);
 378→
 379→  // Handle notify results (zip, selected-zips, bulk-action-notify)
 380→  useEffect(() => {
 381→    if (
 382→      fetcher.data &&
 383→      "action" in fetcher.data &&
 384→      (fetcher.data.action === "notify-zip" || fetcher.data.action === "notify-selected-zips" || fetcher.data.action === "bulk-action-notify")
 385→    ) {
 386→      const data = fetcher.data as {
 387→        action: string;
 388→        zipCode?: string;
 389→        emails: string[];
 390→        count: number;
 391→        zipBreakdown?: { zipCode: string; count: number }[];
 392→      };
 393→      if (data.action === "notify-zip") {
 394→        setNotifyResult({ zipCode: data.zipCode!, emails: data.emails, count: data.count });
 395→      } else {
 396→        setNotifyResult({
 397→          zipCode: data.zipBreakdown?.map(z => z.zipCode).join(", ") ?? "",
 398→          emails: data.emails,
 399→          count: data.count,
 400→        });
 401→      }
 402→      setNotifyResultModalOpen(true);
 403→      setSelectedZips(new Set());
 404→    }
 405→  }, [fetcher.data]);
 406→
 407→  const filteredEntries = useMemo(() => {
 408→    let filtered = entries as WaitlistEntry[];
 409→    if (searchQuery.trim()) {
 410→      const q = searchQuery.trim().toLowerCase();
 411→      filtered = filtered.filter(
 412→        (e) =>
 413→          e.email.toLowerCase().includes(q) ||
 414→          e.zipCode.toLowerCase().includes(q) ||
 415→          (e.note && e.note.toLowerCase().includes(q)),
 416→      );
 417→    }
 418→    if (statusFilter !== "all") {
 419→      filtered = filtered.filter((e) => e.status === statusFilter);
 420→    }
 421→    return filtered;
 422→  }, [entries, searchQuery, statusFilter]);
 423→
 424→  const totalPages = Math.max(1, Math.ceil(filteredEntries.length / PAGE_SIZE));
 425→  const paginatedEntries = useMemo(() => {
 426→    const start = (currentPage - 1) * PAGE_SIZE;
 427→    return filteredEntries.slice(start, start + PAGE_SIZE);
 428→  }, [filteredEntries, currentPage]);
 429→
 430→  const handleSearchChange = useCallback((val: string) => {
 431→    setSearchQuery(val);
 432→    setCurrentPage(1);
 433→  }, []);
 434→
 435→  const handleFilterChange = useCallback((val: string) => {
 436→    setStatusFilter(val);
 437→    setCurrentPage(1);
 438→  }, []);
 439→
 440→  const handleAdd = useCallback(() => {
 441→    if (!newEmail.trim() || !newZipCode.trim()) return;
 442→    const fd = new FormData();
 443→    fd.set("intent", "add");
 444→    fd.set("email", newEmail);
 445→    fd.set("zipCode", newZipCode);
 446→    fd.set("note", newNote);
 447→    fetcher.submit(fd, { method: "POST" });
 448→  }, [newEmail, newZipCode, newNote, fetcher]);
 449→
 450→  const handleDelete = useCallback(
 451→    (id: string) => {
 452→      const fd = new FormData();
 453→      fd.set("intent", "delete");
 454→      fd.set("id", id);
 455→      fetcher.submit(fd, { method: "POST" });
 456→    },
 457→    [fetcher],
 458→  );
 459→
 460→  const handleStatusChange = useCallback(
 461→    (id: string, status: string) => {
 462→      const fd = new FormData();
 463→      fd.set("intent", "update-status");
 464→      fd.set("id", id);
 465→      fd.set("status", status);
 466→      fetcher.submit(fd, { method: "POST" });
 467→    },
 468→    [fetcher],
 469→  );
 470→
 471→  useEffect(() => {
 472→    if (fetcher.state === "idle" && fetcher.data) {
 473→      if ("success" in fetcher.data && fetcher.data.success) {
 474→        const fetcherAction =
 475→          "action" in fetcher.data ? fetcher.data.action : "";
 476→        if (fetcherAction === "added") {
 477→          shopify.toast.show("Added to waitlist");
 478→          setAddModalOpen(false);
 479→          setNewEmail("");
 480→          setNewZipCode("");
 481→          setNewNote("");
 482→        } else if (fetcherAction === "deleted") {
 483→          shopify.toast.show("Entry removed");
 484→        } else if (fetcherAction === "updated") {
 485→          shopify.toast.show("Status updated");
 486→        } else if (fetcherAction === "accepted") {
 487→          shopify.toast.show("ZIP code accepted and added to allowed list");
 488→        } else if (fetcherAction === "rejected") {
 489→          shopify.toast.show("Request rejected");
 490→        } else if (fetcherAction === "deleted-notified") {
 491→          shopify.toast.show("Notified entries cleared");
 492→        } else if (fetcherAction === "bulk-accepted") {
 493→          const count = "count" in fetcher.data ? fetcher.data.count : 0;
 494→          shopify.toast.show(`${count} entries accepted`);
 495→        } else if (fetcherAction === "bulk-rejected") {
 496→          const count = "count" in fetcher.data ? fetcher.data.count : 0;
 497→          shopify.toast.show(`${count} entries rejected`);
 498→        } else if (fetcherAction === "bulk-deleted") {
 499→          const count = "count" in fetcher.data ? fetcher.data.count : 0;
 500→          shopify.toast.show(`${count} entries deleted`);
 501→        }
 502→      }
 503→    }
